196: function createPlayerWeapon() {
197:   const group = new THREE.Group();
198:   const dark = new THREE.MeshLambertMaterial({ color: '#343a35', flatShading: true });
199:   const metal = new THREE.MeshLambertMaterial({ map: metalTexture(1, 1, '#353a37'), color: '#c4c0ac', flatShading: true });
200:   const wood = new THREE.MeshLambertMaterial({ map: woodTexture(), color: side === 'NATO' ? '#423c2c' : '#694b2d', flatShading: true });
201:   box(group, 'receiver', [0.16, 0.16, 0.62], [0, 0, -0.29], dark);
202:   box(group, 'handguard', [0.13, 0.13, 0.38], [0, -0.015, -0.68], side === 'NATO' ? dark : wood);
203:   box(group, 'stock', [0.12, 0.14, 0.34], [0, -0.005, 0.12], side === 'NATO' ? dark : wood);
204:   const barrel = cylinder(group, 'barrel', 0.022, 0.028, 0.58, [0, 0.035, -0.96], metal, 6);
205:   barrel.rotation.x = Math.PI / 2;
206:   box(group, 'magazine', [0.105, 0.3, 0.14], [0, -0.2, -0.32], side === 'NATO' ? dark : wood, [0.18, 0, 0]);
207:   box(group, 'rear sight', [0.08, 0.08, 0.07], [0, 0.1, -0.12], metal);
208:   box(group, 'front sight', [0.04, 0.1, 0.05], [0, 0.095, -0.98], metal);
209:   // Sleeves and gloved hands, framing the weapon in first person.
210:   const sleeveColor = side === 'NATO' ? '#555b43' : '#66634e';
211:   const sleeve = mat(sleeveColor);
212:   const glove = mat('#45443a');
213:   for (const sign of [-1, 1]) {
214:     const arm = box(group, 'sleeve', [0.22, 0.25, 0.48], [sign * 0.24, -0.25, -0.25], sleeve, [0, sign * 0.2, sign * -0.16]);
215:     arm.material = sleeve;
216:     box(group, 'glove', [0.19, 0.16, 0.21], [sign * 0.15, -0.19, -0.52], glove, [0, sign * 0.15, 0]);
217:   }
218:   group.position.set(0.38, -0.36, -0.42);
219:   camera.add(group);
