224: function createEnemy(x, z, index) {
225:   const root = new THREE.Group();
226:   root.position.set(x, 0, z);
227:   root.userData = { health: 100 + wave * 12, maxHealth: 100 + wave * 12, cooldown: 1.1 + Math.random() * 1.6, speed: 0.55 + Math.random() * 0.22, phase: Math.random() * 6.28, alive: true };
228:   const wp = side === 'NATO';
229:   const uniform = mat(wp ? '#555c48' : '#6b694e');
230:   const pants = mat(wp ? '#494d3d' : '#575744');
231:   const helmet = mat(wp ? '#464c3a' : '#51523f');
232:   const skin = mat('#9c8268');
233:   const gear = mat(wp ? '#343b32' : '#454438');
234:   box(root, 'torso', [0.55, 0.72, 0.32], [0, 1.23, 0], uniform);
235:   box(root, 'webbing', [0.58, 0.18, 0.34], [0, 1.27, -0.018], gear);
236:   box(root, 'belt', [0.56, 0.11, 0.34], [0, 0.9, 0], gear);
237:   for (const s of [-1, 1]) {
238:     box(root, 'leg', [0.22, 0.57, 0.26], [s * 0.15, 0.56, 0], pants, [s * 0.04, 0, s * 0.025]);
239:     box(root, 'boot', [0.24, 0.14, 0.34], [s * 0.15, 0.16, -0.035], gear);
240:     box(root, 'arm', [0.19, 0.57, 0.22], [s * 0.36, 1.26, -0.05], uniform, [s * -0.18, 0, s * -0.14]);
241:   }
242:   const head = box(root, 'head', [0.27, 0.31, 0.27], [0, 1.78, 0], skin);
243:   const hat = wp
244:     ? cylinder(root, 'M1 helmet', 0.2, 0.23, 0.15, [0, 1.97, 0], helmet, 8)
245:     : cylinder(root, 'SSh-68 helmet', 0.17, 0.21, 0.28, [0, 1.97, 0], helmet, 7);
246:   box(root, 'rifle', [0.1, 0.11, 0.78], [0.08, 1.2, -0.44], mat('#343831'), [0.06, 0, 0.08]);
247:   const hitbox = new THREE.Mesh(new THREE.BoxGeometry(0.9, 2.05, 0.62), new THREE.MeshBasicMaterial({ visible: false }));
248:   hitbox.position.y = 1.04;
249:   hitbox.userData.enemyRoot = root;
250:   root.add(hitbox);
251:   hitMeshes.push(hitbox);
252:   root.traverse((object) => { if (object.isMesh && object !== hitbox) object.userData.enemyRoot = root; });
253:   world.add(root);
254:   enemies.push(root);
255:   return root;
256: }
