263: function spawnWave() {
264:   wave += 1;
265:   const count = 3 + wave * 2;
266:   for (let i = 0; i < count; i++) {
267:     const lane = [-8.7, -5.7, -2.8, 0, 2.8, 5.7, 8.7][Math.floor(Math.random() * 7)];
268:     createEnemy(lane + (Math.random() - 0.5) * 1.25, -44 - Math.random() * 24 - (i % 3) * 2, i);
269:   }
270:   ui.wave.textContent = wave;
271:   ui.objective.textContent = `ELIMINA LA OLEADA ${wave}`;
272:   ui.enemyCount.textContent = enemies.length;
273:   const banner = $('wave-banner');
274:   $('wave-banner-num').textContent = String(wave).padStart(2, '0');
275:   $('wave-banner-sub').textContent = wave === 5 ? 'OLEADA FINAL · NO CEDAS TERRENO' : 'MANTÉN LA POSICIÓN';
276:   banner.classList.remove('show');
277:   void banner.offsetWidth;
278:   banner.classList.add('show');
279:   addFeed(`OLEADA ${wave}`, `${count} HOSTILES`);
280: }
