282: function addFeed(title, detail = '') {
283:   const feed = $('feed');
284:   const row = document.createElement('span');
285:   row.innerHTML = `<b>${title}</b>${detail ? ` · ${detail}` : ''}`;
286:   feed.prepend(row);
287:   while (feed.children.length > 4) feed.lastElementChild.remove();
288:   setTimeout(() => row.remove(), 4800);
289: }
