296: function updateHud() {
297:   ui.health.textContent = Math.ceil(health);
298:   ui.healthBar.style.width = `${Math.max(0, health)}%`;
299:   ui.armor.textContent = Math.ceil(armor);
300:   ui.armorBar.style.width = `${Math.max(0, armor)}%`;
301:   ui.ammo.textContent = ammo;
302:   ui.reserve.textContent = reserveAmmo;
303:   ui.grenades.textContent = grenades;
