322:   weaponSlot = 1;
323:   ammo = weaponInfo().mag; reserveAmmo = 120;
324:   weaponStocks = { 1: { ammo, reserve: reserveAmmo }, 2: { ammo: 7, reserve: 35 } };
325:   grenades = 2;
326:   fireCooldown = 0; reloadTimer = 0; damageTimer = 0; toastTimer = 0;
327:   gameTime = 0; waveDelay = 1.25; startTime = performance.now();
328:   player.x = 0; player.z = 5; player.y = 1.68; player.vx = 0; player.vz = 0;
329:   yaw = 0; pitch = 0; camera.rotation.set(0, 0, 0); camera.position.set(0, player.y, 5);
