345:     : 'Fuerzas del Pacto de Varsovia avanzan por la avenida. Mantén la posición y elimina cinco oleadas enemigas.';
346:   $('hud-faction').textContent = wp ? 'PACTO DE VARSOVIA' : 'OTAN';
347:   $('hud-unit-name').textContent = wp ? '6.ª BRIGADA MOTORIZADA' : 'BERLIN BRIGADE';
348:   $('hud-badge').textContent = wp ? '★' : '✦';
349:   $('hud-badge').style.color = wp ? 'var(--wp)' : 'var(--nato)';
