355: function isTouchDevice() { return matchMedia('(pointer: coarse)').matches; }
356: function setPaused(value) {
357:   if (!running && value) return;
358:   paused = value;
359:   ui.pause.classList.toggle('hidden', !paused);
360:   if (paused) {
361:     if (document.pointerLockElement === canvas) document.exitPointerLock();
362:   } else if (!isTouchDevice()) canvas.requestPointerLock?.();
363: }
364: function finishMission(win) {
365:   running = false; paused = false;
366:   ui.hud.classList.add('hidden'); ui.pause.classList.add('hidden');
367:   const card = ui.result.querySelector('.result-card');
368:   card.classList.toggle('win', win); card.classList.toggle('loss', !win);
369:   $('result-kicker').textContent = win ? 'INFORME DE COMBATE · SECTOR CHARLIE' : 'INFORME DE COMBATE · MISIÓN FALLIDA';
370:   $('result-title').innerHTML = win ? 'SECTOR<br>ASEGURADO' : 'POSICIÓN<br>PERDIDA';
