580: export function ps1ify(material, enabled = true) {
581:   if (!enabled) return material;
582:   material.onBeforeCompile = (shader) => {
583:     shader.uniforms.uSnap = { value: snapResolution };
584:     shader.vertexShader = 'uniform vec2 uSnap;\n' + shader.vertexShader;
585:     shader.vertexShader = shader.vertexShader.replace(
586:       '#include <project_vertex>',
587:       `
588:       vec4 mvPosition = vec4( transformed, 1.0 );
589:       #ifdef USE_INSTANCING
590:         mvPosition = instanceMatrix * mvPosition;
591:       #endif
592:       mvPosition = modelViewMatrix * mvPosition;
593:       gl_Position = projectionMatrix * mvPosition;
594:       vec2 snapNdc = gl_Position.xy / gl_Position.w;
595:       vec2 grid = uSnap * 0.5;
596:       snapNdc = floor(snapNdc * grid + 0.5) / grid;
597:       gl_Position.xy = snapNdc * gl_Position.w;
598:       `
599:     );
600:   };
601:   material.customProgramCacheKey = () => 'ps1snap';
602:   return material;
603: }
