381: function fire() {
382:   if (!running || paused || reloadTimer > 0 || fireCooldown > 0) return;
383:   if (ammo <= 0) { showToast('SIN MUNICIÓN · PULSA R'); fireCooldown = 0.25; return; }
384:   const pistol = weaponSlot === 2;
385:   ammo--; shots++;
386:   fireCooldown = pistol ? 0.32 : weaponInfo().interval;
387:   gunKick = Math.min(0.16, gunKick + (pistol ? 0.09 : 0.055));
388:   raycaster.setFromCamera(center, camera);
389:   raycaster.far = 90;
390:   const active = enemies.filter((enemy) => enemy.userData.alive);
391:   const targets = active.flatMap((enemy) => enemy.children.filter((child) => child.isMesh));
392:   const hitscan = raycaster.intersectObjects([...targets, ...colliders], false);
393:   const first = hitscan[0];
394:   if (first && first.object.userData.enemyRoot) {
395:     const enemy = first.object.userData.enemyRoot;
396:     if (enemy.userData.alive) {
397:       const damage = pistol ? 52 : weaponInfo().damage;
398:       enemy.userData.health -= damage;
399:       hits++;
400:       score += 15;
401:       const marker = $('crosshair').querySelector('.hitmark');
402:       marker.classList.remove('on'); void marker.offsetWidth; marker.classList.add('on');
403:       if (enemy.userData.health <= 0) killEnemy(enemy);
404:     }
405:   }
406:   if (first?.point) spawnTracer(first.point);
407:   if (ammo === 0 && reserveAmmo > 0) showToast('CARGADOR VACÍO · R PARA RECARGAR');
408:   updateHud();
409: }
410: function killEnemy(enemy) {
