415:   if (index >= 0) enemies.splice(index, 1);
416:   const h = hitMeshes.findIndex((mesh) => mesh.userData.enemyRoot === enemy);
417:   if (h >= 0) hitMeshes.splice(h, 1);
418:   enemy.rotation.z = -0.8; enemy.position.y = -0.45;
419:   setTimeout(() => world.remove(enemy), 500);
420:   addFeed('HOSTIL NEUTRALIZADO', `+${100 + wave * 25} PTS`);
