491: function collidesAt(x, z) {
492:   playerBox.min.set(x - 0.34, 0.02, z - 0.34);
493:   playerBox.max.set(x + 0.34, 1.82, z + 0.34);
494:   for (const obstacle of colliders) {
495:     collisionBox.setFromObject(obstacle);
496:     if (playerBox.intersectsBox(collisionBox)) return true;
497:   }
498:   return false;
499: }
500: function movePlayer(dt) {
501:   const forward = (keys.KeyW || keys.ArrowUp ? 1 : 0) - (keys.KeyS || keys.ArrowDown ? 1 : 0) - touch.moveY;
502:   const strafe = (keys.KeyD || keys.ArrowRight ? 1 : 0) - (keys.KeyA || keys.ArrowLeft ? 1 : 0) + touch.moveX;
503:   const input = new THREE.Vector2(strafe, forward);
504:   if (input.lengthSq() > 1) input.normalize();
505:   const speed = player.crouch ? 2.45 : 5.2;
506:   const sin = Math.sin(yaw), cos = Math.cos(yaw);
507:   const dx = (input.x * cos - input.y * sin) * speed * dt;
508:   const dz = (-input.x * sin - input.y * cos) * speed * dt;
509:   const nx = THREE.MathUtils.clamp(player.x + dx, -11.9, 11.9);
510:   if (!collidesAt(nx, player.z)) player.x = nx;
511:   const nz = THREE.MathUtils.clamp(player.z + dz, -71, 13.8);
512:   if (!collidesAt(player.x, nz)) player.z = nz;
513:   isMoving = input.lengthSq() > 0.025;
514:   if (isMoving) bobTime += dt * (player.crouch ? 7 : 10);
515:   const bob = isMoving ? Math.sin(bobTime) * (player.crouch ? 0.018 : 0.035) : 0;
516:   player.y = THREE.MathUtils.damp(player.y, player.crouch ? 1.12 : 1.68, 12, dt);
517:   camera.position.set(player.x, player.y + bob, player.z);
518:   camera.rotation.set(pitch, yaw, 0, 'YXZ');
519: }
520: function damagePlayer(amount) {
521:   const absorbed = Math.min(armor, amount * 0.62);
522:   armor -= absorbed;
523:   health -= amount - absorbed;
524:   damageTimer = 0.24;
525:   $('damage-flash').classList.add('on');
526:   updateHud();
527:   if (health <= 0) { health = 0; updateHud(); finishMission(false); }
528: }
529: function updateEnemies(dt) {
530:   for (const enemy of [...enemies]) {
531:     const data = enemy.userData;
532:     if (!data.alive) continue;
533:     const dx = player.x - enemy.position.x;
534:     const dz = player.z - enemy.position.z;
535:     const distance = Math.hypot(dx, dz);
536:     const goalZ = -13 + Math.min(4, wave * 0.45);
537:     if (enemy.position.z < goalZ) {
538:       enemy.position.x += THREE.MathUtils.clamp(dx, -1, 1) * data.speed * 0.42 * dt;
539:       enemy.position.z += Math.min(goalZ - enemy.position.z, data.speed * dt);
540:     }
541:     enemy.rotation.y = Math.atan2(dx, dz);
542:     data.phase += dt * 5;
543:     enemy.position.y = Math.abs(Math.sin(data.phase)) * 0.025;
544:     data.cooldown -= dt;
545:     if (distance < 48 && data.cooldown <= 0) {
546:       data.cooldown = 1.25 + Math.random() * 1.25;
547:       const chance = THREE.MathUtils.clamp(0.72 - distance / 95, 0.2, 0.62);
548:       if (Math.random() < chance) damagePlayer(5 + Math.random() * 8);
