mkdirSync('/tmp/opencode',{recursive:true});
const desktop=await browser.newPage({viewport:{width:1024,height:768}});
const errors=[]; desktop.on('pageerror',e=>errors.push(e.message));
await desktop.goto('http://127.0.0.1:3000');
await desktop.waitForSelector('#menu:not(.hidden)');
await desktop.locator('.faction-card.wp').click();
await desktop.locator('#brief-go').click();
await desktop.waitForSelector('#hud:not(.hidden)');
await desktop.waitForTimeout(1700);
await desktop.screenshot({path:'/tmp/opencode/checkpoint-game.jpg',type:'jpeg',quality:78});
const startAmmo=await desktop.locator('#ammo-mag').innerText();
await desktop.keyboard.press('Space');
await desktop.waitForTimeout(100);
const firedAmmo=await desktop.locator('#ammo-mag').innerText();
await desktop.keyboard.press('g');
const grenades=await desktop.locator('#grenade-count').innerText();
await desktop.keyboard.press('2');
const pistol=await desktop.locator('#weapon-name').innerText();
await desktop.keyboard.press('r');
await desktop.waitForTimeout(1300);
const pistolAmmo=await desktop.locator('#ammo-mag').innerText();
await desktop.keyboard.press('Escape');
await desktop.locator('#quit-btn').click();
await desktop.locator('.faction-card.nato').click();
await desktop.locator('#brief-go').click();
await desktop.waitForTimeout(2200);
const desktopState={side:await desktop.locator('#hud-faction').innerText(),startAmmo,firedAmmo,grenades,pistol,pistolAmmo,errors};
// Mobile landscape smoke: confirm touch controls activate, stick movement, and fire.
const mobile=await browser.newPage({viewport:{width:844,height:390}, isMobile:true, hasTouch:true, deviceScaleFactor:1});
mobile.on('pageerror',e=>errors.push(e.message));
await mobile.goto('http://127.0.0.1:3000');
await mobile.waitForSelector('#menu:not(.hidden)');
await mobile.locator('.faction-card.nato').click();
await mobile.locator('#brief-go').click();
await mobile.waitForSelector('#hud:not(.hidden)');
await mobile.waitForTimeout(1500);
const touchVisible=await mobile.locator('#touch-ui').evaluate(e=>getComputedStyle(e).display!=='none');
const before=await mobile.locator('#ammo-mag').innerText();
const fire=mobile.locator('#btn-fire');
const box=await fire.boundingBox();
await mobile.touchscreen.tap(box.x+box.width/2,box.y+box.height/2);
await mobile.waitForTimeout(100);
const after=await mobile.locator('#ammo-mag').innerText();
const reload=mobile.locator('#btn-reload');
const rb=await reload.boundingBox();
await mobile.touchscreen.tap(rb.x+rb.width/2,rb.y+rb.height/2);
await mobile.waitForTimeout(1800);
const mobileState={touchVisible,before,after,afterReload:await mobile.locator('#ammo-mag').innerText(),errors};
await mobile.screenshot({path:'/tmp/opencode/checkpoint-mobile.jpg',type:'jpeg',quality:76});
console.log(JSON.stringify({desktopState,mobileState}));
await browser.close();
